#include <iostream>
#include <string>

int main() {
    int count{42};
    double price{9.99};
    bool inStock{true};
    char grade{'A'};
    std::string name{"Ada"};

    std::cout << "count: " << count << '\n';
    std::cout << "price: " << price << '\n';
    std::cout << "inStock: " << inStock << '\n';
    std::cout << "grade: " << grade << '\n';
    std::cout << "name: " << name << " (" << name.size() << " chars)\n";
}

#include <iostream>

int main() {
    int total{7};
    int parts{2};

    std::cout << total / parts << '\n';                       // integer division
    std::cout << total % parts << '\n';                       // remainder
    std::cout << static_cast<double>(total) / parts << '\n';  // real division
    std::cout << 7.0 / 2 << '\n';                             // a double literal does the same

    int truncated = 3.99;   // allowed with =, silently loses .99
    std::cout << truncated << '\n';
}

#include <iostream>
#include <string>

int main() {
    auto n = 42;                      // int
    auto ratio = 2.5;                 // double
    auto flag = false;                // bool
    auto text = "hi";                 // const char*, NOT std::string
    auto name = std::string{"Grace"}; // std::string, say so explicitly

    std::cout << n * 2 << ' ' << ratio * 2 << ' ' << flag << '\n';
    std::cout << name.size() << '\n';
    std::cout << text << '\n';
}

